/* Product extensions share the original application state. */
'use strict';
const Sort=MedSorter,Quality=MedQuality;
let sortPlan=null,sortFiles=new Map(),sortSkipped=[],sortMode='browser',gatewaySession={url:'',token:''},aiSessionStatus=null;
function projectExtensions(){project.brand={product:'MedAnnotate',studio:'Eye Candy Studio',research:'Atom Research'};project.sortSecret??=Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('');project.release??={version:'',steward:'Atom Research',licenseName:'',licenseText:'',sourceReference:'',authorizationReference:'',deidentificationMethod:'',intendedUse:'',limitations:'',commercialAuthorized:false};project.audit??=[];}
function audit(action,details={}){projectExtensions();project.audit.push({at:new Date().toISOString(),action,...details});changed()}
const hex=buffer=>Array.from(new Uint8Array(buffer),b=>b.toString(16).padStart(2,'0')).join('');async function hashBytes(bytes){return hex(await crypto.subtle.digest('SHA-256',bytes))}
async function sortToken(text){projectExtensions();const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(project.sortSecret),{name:'HMAC',hash:'SHA-256'},false,['sign']);return hex(await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(text))).slice(0,20)}
function sortExtension(name,format){return format==='DICOM'?'.dcm':/\.nii\.gz$/i.test(name)?'.nii.gz':'.'+name.split('.').at(-1).toLowerCase()}
async function scanBrowser(files){sortMode='browser';sortFiles=new Map();const rows=[],skipped=[],hashes=new Set();let count=0,total=0;for(const f of files){if(f.name.startsWith('.'))continue;try{C.check(f.size<=600*1024*1024,'File exceeds 600 MB');const bytes=new Uint8Array(await f.arrayBuffer()),meta=Sort.metadata(bytes,f.name),hash=await hashBytes(bytes),relative=f.webkitRelativePath||f.name,rowId=await sortToken(Sort.recordKey(meta,hash,relative)),record={relative,size:f.size,hash,extension:sortExtension(f.name,meta.format),rowId,studyKey:await sortToken('study:'+(meta.study||rowId)),group:'P_'+await sortToken(meta.subject||'unlinked:'+rowId),meta,suggestion:Sort.classify(meta,relative),duplicateOf:meta.format==='FILE'?null:hashes.has(hash)?hash:null};hashes.add(hash);if(!sortFiles.has(hash))sortFiles.set(hash,f);Sort.mergeRecord(rows,record);total+=f.size}catch(e){skipped.push({name:f.name,reason:e.message})}if(++count%10===0){message('Scanning locally: '+count+' files…');await new Promise(r=>setTimeout(r,0))}}sortPlan={id:crypto.randomUUID(),rows,files:count,bytes:total,skipped};sortSkipped=skipped;renderSorter()}
bind('sorter',()=>{projectExtensions();modal(`<h2>Sort before annotation</h2><p>Scan a mixed folder, then automatically organize a copy or review individual groups. Unknown and conflicting files are kept in REVIEW. Originals stay in place.</p><div class="info-box">Sorted originals retain their source DICOM headers and may contain identifying data. Keep them in your approved environment. Sorting does not de-identify images.</div><div class="button-pair"><button id="scanBrowser" class="primary">Choose mixed folder</button>${window.medDesktop?'<button id="scanDesktop">Scan desktop folders</button>':''}</div><div id="sortResults"></div>`);bind('scanBrowser',()=>$('sortInput').click());if(window.medDesktop)bind('scanDesktop',async()=>{message('Scanning the selected folder…');const p=await medDesktop.scanFolders(project.sortSecret);if(p){sortMode='desktop';sortPlan=p;sortSkipped=p.skipped;renderSorter()}});if(sortPlan)renderSorter()});
$('sortInput').onchange=safe(async e=>{await scanBrowser([...e.target.files]);e.target.value=''});if(window.medDesktop)medDesktop.onProgress(v=>message(v.completed?'Verified file operations: '+v.completed:'Scanning: '+v.files+' files / '+v.series+' series'));
function rowCount(r){return r.count??r.files.length}function duplicateCount(r){return r.duplicates??r.files.filter(f=>f.duplicateOf).length}
function renderSorter(){if(!$('sortResults'))return;const rows=sortPlan.rows;$('sortResults').innerHTML=`<p><b>${sortPlan.files}</b> files scanned · <b>${rows.length}</b> series · ${sortSkipped.length} skipped</p><p class="hint">Anatomy suggestions use metadata and path words, not pixel AI. Automatic copy uses clear metadata; filename hints and conflicts go to REVIEW. Subject IDs are pseudonyms; missing patient identifiers remain separate.</p><div class="button-pair"><button id="sortAutoCopy" class="primary">Automatically organize all files</button>${sortMode==='browser'?'<button id="sortAutoZip">Download automatic sorted ZIP</button>':''}</div><p class="hint">Automatic sorting is copy-only and does not mark any case reviewed. Unsupported formats retain their original relative paths under REVIEW / ORIGINAL_FILES.</p><div class="sort-table"><table><thead><tr><th>Use</th><th>Series</th><th>Anatomy</th><th>Subject group</th><th>Confirmed</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><input type="checkbox" data-use="${i}" aria-label="Select series ${i+1}"></td><td><b>${esc(r.description)}</b><small>${esc(r.modality)} · ${rowCount(r)} files · ${duplicateCount(r)} duplicates</small><small>${esc(r.confidence)} · ${esc(r.evidence)}</small>${r.annotationCandidate===false?`<small>${esc(r.sortOnlyReason)}</small>`:''}${r.subjectNeedsReview?'<small class="error">Subject identity missing: check grouping</small>':''}</td><td><select data-category="${i}" aria-label="Anatomy">${Sort.categories.map(c=>`<option ${r.category===c?'selected':''}>${c}</option>`).join('')}</select></td><td><input data-subject="${i}" aria-label="Subject group" value="${esc(r.group)}"></td><td><input type="checkbox" data-confirm="${i}" aria-label="Confirm anatomy and subject group"></td></tr>`).join('')}</tbody></table></div><label class="check"><input id="sortConsent" type="checkbox">I reviewed anatomy and subject grouping for the selected series.</label><div class="button-pair"><button id="sortCopy" class="primary">Create folders and copy</button><button id="sortImport">Open selected for annotation</button></div>${sortMode==='desktop'?'<button id="sortMove" class="wide">Move verified originals to destination…</button>':'<button id="sortZip" class="wide">Download sorted ZIP (small batches)</button>'}<p class="hint">Folder structure: Anatomy / Modality / Subject / Study / Series. No source file is overwritten. Duplicates stay in the original folder.</p>${sortSkipped.length?`<details><summary>Skipped files</summary><pre>${esc(sortSkipped.slice(0,100).map(x=>x.name+': '+x.reason).join('\n'))}</pre></details>`:''}`;bind('sortAutoCopy',()=>executeSort(false,false,true));if(sortMode==='browser')bind('sortAutoZip',()=>executeSort(false,true,true));bind('sortCopy',()=>executeSort(false,false));if(sortMode==='desktop')bind('sortMove',()=>executeSort(true,false));else bind('sortZip',()=>executeSort(false,true));bind('sortImport',importSorted)}
function sortDecisions(){C.check($('sortConsent').checked,'Confirm the sorting review first');const out=[];for(let i=0;i<sortPlan.rows.length;i++){if(!$('sortResults').querySelector(`[data-use="${i}"]`).checked)continue;const category=$('sortResults').querySelector(`[data-category="${i}"]`).value,group=$('sortResults').querySelector(`[data-subject="${i}"]`).value.trim(),confirmed=$('sortResults').querySelector(`[data-confirm="${i}"]`).checked;C.check(confirmed,'Confirm every selected series, or use automatic sorting');Sort.safeName(group);out.push({id:sortPlan.rows[i].id,category,group,confirmed})}C.check(out.length,'Select one or more series');return out}
async function getSortBytes(record){const file=sortFiles.get(record.hash),bytes=new Uint8Array(await file.arrayBuffer());C.check(await hashBytes(bytes)===record.hash,'Source changed after scan; scan again');return bytes}
let sortExecuting=false;
async function executeSort(move,zip,automatic=false){
 C.check(!sortExecuting,'Sorting is already running');sortExecuting=true;
 const controls=[...$('dialogBody').querySelectorAll('button')];controls.forEach(b=>b.disabled=true);
 try{return await executeSortRun(move,zip,automatic)}finally{sortExecuting=false;controls.forEach(b=>b.disabled=false)}
}
async function executeSortRun(move,zip,automatic=false){const decisions=automatic?Sort.automaticDecisions(sortPlan.rows):sortDecisions();C.check(decisions.length,'No files to sort');if(sortMode==='desktop'){const result=await medDesktop.executeSort({planId:sortPlan.id,decisions,move,automatic});if(!result)return;const failed=result.files.filter(x=>x.status==='failed-original-retained').length;audit('sort-files',{mode:result.mode,files:result.files.length,failures:failed});message(`Sorting finished: ${result.files.length-failed} processed/skipped, ${failed} failed. Check the destination transfer log.`,!!failed);return}C.check(!move,'Moving source files is available in the desktop application');let root;if(!zip){C.check(window.showDirectoryPicker,'This browser cannot write folders. Use Download sorted ZIP or the desktop app.');root=await showDirectoryPicker({mode:'readwrite'})}const selected=sortPlan.rows.filter(r=>decisions.some(d=>d.id===r.id)),total=selected.reduce((n,r)=>n+r.files.reduce((m,f)=>m+f.size,0),0);C.check(!zip||total<=400*1024*1024,'ZIP sorting is limited to 400 MB. Use folder copy or the desktop app.');const copied=new Map(),archive={},manifest={classification:automatic?'automatic-unreviewed':'user-reviewed',mode:zip?'sorted-download':'copy',created:new Date().toISOString(),note:'Original metadata retained. Not de-identified.',files:[]};for(const row of selected){const d=decisions.find(d=>d.id===row.id);for(const f of row.files){if(row.format!=='FILE'&&copied.has(f.hash)){manifest.files.push({sha256:f.hash,status:'duplicate-skipped',duplicateOf:copied.get(f.hash)});continue}const bytes=await getSortBytes(f),destination=Sort.destination({...row,category:d.category,group:d.group},f);if(zip)archive[destination]=bytes;else{const parts=destination.split('/');let dir=root;for(const part of parts.slice(0,-1))dir=await dir.getDirectoryHandle(part,{create:true});let exists=false;try{await dir.getFileHandle(parts.at(-1));exists=true}catch(e){if(e.name!=='NotFoundError')throw e}C.check(!exists,'Destination already contains '+destination+'. No files were overwritten.');const handle=await dir.getFileHandle(parts.at(-1),{create:true}),stream=await handle.createWritable();try{await stream.write(bytes);await stream.close()}catch(e){await stream.abort().catch(()=>{});throw e}C.check(await hashBytes(await (await handle.getFile()).arrayBuffer())===f.hash,'Destination verification failed; source retained')}copied.set(f.hash,destination);manifest.files.push({destination,sha256:f.hash,status:zip?'included-in-archive':'copied-and-verified'});if(root)await flushSortReceipt(root,manifest)}}if(zip){archive['sort-manifest.json']=JSON.stringify(manifest,null,2);download(C.zip(archive),'MedAnnotate-sorted-originals.zip')}else{const handle=await root.getFileHandle('MedAnnotate-sort-'+sortPlan.id+'.json',{create:true}),s=await handle.createWritable();await s.write(JSON.stringify(manifest,null,2));await s.close()}audit('sort-files',{mode:manifest.mode,files:manifest.files.length});message('Sorting completed. Originals were retained. You can now open selected series for annotation.')}
async function importSorted(){const decisions=sortDecisions();C.check(decisions.every(d=>sortPlan.rows.find(r=>r.id===d.id).annotationCandidate!==false),'Some selected files are sorting-only. Select supported images for annotation.');let imported=0;for(const d of decisions){const row=sortPlan.rows.find(r=>r.id===d.id),before=project.cases.length;let files;if(sortMode==='desktop'){files=(await medDesktop.readSeries(sortPlan.id,row.id)).map(f=>{const file=new File([f.bytes],f.name);file.medOriginalPath=f.originalSource;return file})}else files=row.files.filter(f=>!f.duplicateOf).map(f=>sortFiles.get(f.hash));await importFiles(files);for(const c of project.cases.slice(before)){c.group=d.group;if(typeof syncPrivateGroup==='function')await syncPrivateGroup(c.id,d.group);c.anatomy=d.category;c.modality=row.modality;c.sourceSeriesKey=row.id;c.sortReviewedAt=new Date().toISOString();c.sourceFileHashes=sortMode==='browser'?row.files.filter(f=>!f.duplicateOf).map(f=>f.hash):(row.sourceHashes||[]);imported++}}audit('import-sorted-series',{count:imported});renderAll();$('dialog').close();message('Opened '+imported+' sorted volume(s). Confirm acquisition checks before annotation.')}
const providerLabels={openai:'OpenAI / GPT',anthropic:'Anthropic / Claude',deepseek:'DeepSeek',compatible:'Compatible API / local model'};
function assistantContext(){const c=current();return {product:'MedAnnotate by Eye Candy Studio for Atom Research',protocol:{labels:project.labels,classFields:project.classFields,requiredLandmarks:project.landmarkDefinitions,expectedParameters:project.protocol},case:c?{caseId:c.id,anatomy:c.anatomy||'Unspecified',modality:c.modality,dimensions:c.dims,geometry:c.geometry,status:c.status,classification:c.classification,checklist:c.checklist,maskStatistics:Quality.statistics(c,project.labels)}:null}}
function currentSlicePNG(){const c=current();C.check(c,'Open an image first');const p=C.plane(c.dims,axis,k),canvas=document.createElement('canvas');canvas.width=p.w;canvas.height=p.h;const cc=canvas.getContext('2d'),img=cc.createImageData(p.w,p.h),width=Math.max(.01,+$('window').value),level=+$('level').value;for(let y=0;y<p.h;y++)for(let x=0;x<p.w;x++){let grey=Math.max(0,Math.min(255,(c.data[p.index(x,y)]-level+width/2)*255/width));if(c.inverse)grey=255-grey;const i=(x+y*p.w)*4;img.data[i]=img.data[i+1]=img.data[i+2]=grey;img.data[i+3]=255}cc.putImageData(img,0,0);return canvas.toDataURL('image/png')}
async function gatewayCall(path,payload){const url=new URL(gatewaySession.url);C.check(url.protocol==='https:'||(url.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(url.hostname)),'Use HTTPS or a loopback gateway');C.check(gatewaySession.token.length>=24,'Enter your gateway token');url.pathname=url.pathname.replace(/\/$/,'')+path;const response=await fetch(url,{method:payload?'POST':'GET',headers:{Authorization:'Bearer '+gatewaySession.token,...(payload?{'Content-Type':'application/json'}:{})},...(payload?{body:JSON.stringify(payload)}:{}),signal:AbortSignal.timeout(100000),redirect:'error'});C.check(response.ok,'AI gateway returned HTTP '+response.status+'. Check its configuration and access.');return response.json()}
bind('assistant',async()=>{projectExtensions();if(window.medDesktop)aiSessionStatus=await medDesktop.aiStatus();modal(`<h2>AI annotation assistant</h2><p>Protocol guidance, completeness checks and dataset documentation. Advice is unverified and cannot change masks, review status or release permissions.</p>${window.medDesktop?`<details ${aiSessionStatus?.configured?'':'open'}><summary>Provider connection</summary><div class="control-grid"><label>Provider<select id="aiProvider">${Object.entries(providerLabels).map(([v,n])=>`<option value="${v}" ${aiSessionStatus?.provider===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Model ID<input id="aiModel" value="${esc(aiSessionStatus?.model||'')}" placeholder="Model available in your account"></label></div><label>Compatible endpoint (used only for compatible provider)<input id="aiEndpoint" value="${esc(aiSessionStatus?.endpoint||'http://127.0.0.1:11434/v1/chat/completions')}"></label><label>API key<input id="aiKey" type="password" autocomplete="off" placeholder="Leave blank to retain same-provider key"></label><label class="check"><input id="aiVision" type="checkbox" ${aiSessionStatus?.vision?'checked':''}>This exact model accepts image input</label><label class="check"><input id="aiPersist" type="checkbox">Save credentials with OS encryption (otherwise this session only)</label><div class="button-pair"><button id="aiSave">Save connection</button><button id="aiForget">Forget credentials</button></div></details>`:`<details open><summary>AI gateway connection</summary><p class="hint">Run the included gateway locally or on your trusted server. It holds the GPT, Claude, DeepSeek or compatible-provider API key; this page uses a separate gateway token.</p><label>Gateway base URL<input id="gatewayURL" placeholder="http://127.0.0.1:8767" value="${esc(gatewaySession.url)}"></label><label>Gateway token (session only)<input id="gatewayToken" type="password" autocomplete="off"></label><button id="gatewayConnect">Connect gateway</button></details>`}<p id="aiConnection">${aiSessionStatus?.configured?esc(providerLabels[aiSessionStatus.provider]||aiSessionStatus.provider)+' · '+esc(aiSessionStatus.model):'No provider connected'}</p><label>Task<select id="aiTask"><option value="protocol">Explain label boundaries and missing protocol definitions</option><option value="review">Check the annotation review checklist for omissions</option><option value="dataset">Draft dataset-card text from the supplied facts</option><option value="custom">Custom research workflow question</option></select></label><label>Your question<textarea id="aiPrompt" rows="3">Explain the supplied label definitions and identify missing information. Do not invent anatomical boundaries.</textarea></label><details><summary>Preview the exact case context to be sent</summary><pre id="aiContext">${esc(JSON.stringify(assistantContext(),null,2))}</pre></details><label class="check"><input id="aiAttach" type="checkbox">Also send the current windowed slice (vision-capable model required)</label><label class="check"><input id="aiConsent" type="checkbox">I reviewed this prompt/context, checked any image for identifying data, and approve transmission to this provider.</label><button id="aiSend" class="primary wide">Ask assistant</button><pre id="aiAnswer" class="ai-answer" role="status"></pre><button id="aiSaveNote" class="wide" hidden>Save answer as an unverified research note</button>`);
if(window.medDesktop){bind('aiSave',async()=>{aiSessionStatus=await medDesktop.aiConfigure({provider:$('aiProvider').value,model:$('aiModel').value,endpoint:$('aiEndpoint').value,key:$('aiKey').value,vision:$('aiVision').checked,persist:$('aiPersist').checked});$('aiKey').value='';$('aiConnection').textContent=providerLabels[aiSessionStatus.provider]+' · '+aiSessionStatus.model});bind('aiForget',async()=>{aiSessionStatus=await medDesktop.aiForget();$('aiConnection').textContent='Credentials removed'})}else bind('gatewayConnect',async()=>{gatewaySession={url:$('gatewayURL').value.trim().replace(/\/$/,''),token:$('gatewayToken').value};aiSessionStatus=await gatewayCall('/status');$('gatewayToken').value='';$('aiConnection').textContent=providerLabels[aiSessionStatus.provider]+' · '+aiSessionStatus.model});
$('aiTask').onchange=()=>{$('aiPrompt').value={protocol:'Explain the supplied label definitions and identify missing information. Do not invent anatomical boundaries.',review:'List missing or inconsistent review checks using only the supplied facts. Do not infer diagnoses or claim the masks are correct.',dataset:'Draft a short factual dataset description. Explicitly leave unknown provenance, licensing, demographics and validation unspecified.',custom:''}[$('aiTask').value]};bind('aiSend',async()=>{C.check(aiSessionStatus?.configured,'Connect a provider first');C.check($('aiConsent').checked,'Approve transmission first');C.check(!$('aiAttach').checked||aiSessionStatus.vision,'The configured model is not enabled for image input');C.check(!$('aiAttach').checked||current()?.synthetic||current()?.privacy?.state==='approved','Clear privacy intake before transmitting a slice to AI');const context=assistantContext(),payload={prompt:$('aiPrompt').value,context,consent:true,...($('aiAttach').checked?{image:currentSlicePNG()}:{})};$('aiContext').textContent=JSON.stringify(context,null,2);$('aiSend').disabled=true;$('aiAnswer').textContent='Waiting for the provider…';try{const caseId=current()?.id,result=window.medDesktop?await medDesktop.aiAsk(payload):await gatewayCall('/assist',payload);$('aiAnswer').textContent=result.answer;$('aiSaveNote').hidden=false;audit('ai-request',{provider:result.provider,model:result.model,caseId:caseId||null,imageSent:!!payload.image});bind('aiSaveNote',()=>{const note={...result,caseId:caseId||null,verified:false,prompt:payload.prompt};project.researchNotes??=[];project.researchNotes.push(note);audit('ai-note-saved',{provider:result.provider,model:result.model});$('aiSaveNote').hidden=true;message('Saved as an unverified research note. Annotation and review status were not changed.')})}catch(e){$('aiAnswer').textContent=e.message;throw e}finally{$('aiSend').disabled=false}})});
bind('quality',()=>{const c=current();C.check(c,'Open a case first');const stats=Quality.statistics(c,project.labels);modal(`<h2>Quality control · ${esc(c.id)}</h2><p>${stats.geometryKnown?'Volume measurements use the image affine.':'Spatial units are unknown: calibrated volume is unavailable.'} Empty internal slices can reflect separate structures; review them rather than assuming an error.</p><table class="qc-table"><thead><tr><th>Label</th><th>Voxels</th><th>Volume (mL)</th><th>Occupied K slices</th><th>Internal empty slices</th></tr></thead><tbody>${stats.labels.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.voxels.toLocaleString()}</td><td>${r.volumeML===null?'—':r.volumeML.toFixed(3)}</td><td>${r.occupiedKSlices}</td><td>${r.internalEmptyKSlices}</td></tr>`).join('')}</tbody></table><p>${stats.unknownVoxels} voxels use unknown labels.</p><label>Reference annotator ID<input id="referenceRater" placeholder="Pseudonymous reviewer ID"></label><button id="compareMask" class="wide">Compare a second-rater NIfTI mask</button><div id="diceResults"></div><p class="hint">Comparison requires identical dimensions and affine. Dice/IoU measure agreement, not correctness. Both-empty labels report N/A.</p><label>Primary reviewer ID<input id="primaryRater" value="${esc(c.reviewer||'')}" placeholder="Self-reported reviewer ID"></label><button id="setRater">Save reviewer identity</button><hr><label>Independent release reviewer ID<input id="releaseRater" placeholder="Must differ from primary reviewer"></label><label class="check"><input id="releaseCheck" type="checkbox">I independently reviewed the current masks, labels and protocol compliance.</label><button id="approveRelease" class="primary wide">Record independent review</button><p class="hint">Reviewer identities are self-reported in this local version; these are not verified electronic signatures.</p>`);bind('compareMask',()=>{C.check($('referenceRater').value.trim(),'Enter the reference reviewer ID');$('referenceMask').click()});$('referenceMask').onchange=safe(async e=>{const f=e.target.files[0];if(!f)return;let buf=await f.arrayBuffer();if(/\.gz$/i.test(f.name))buf=await ungzip(buf);const reference=C.nifti(buf),results=Quality.compare(c,reference,project.labels);c.agreement={reviewer:$('referenceRater').value.trim(),at:new Date().toISOString(),revision:c.annotationRevision||0,referenceSHA256:await hashBytes(buf),metrics:results};audit('rater-comparison',{caseId:c.id,reviewer:c.agreement.reviewer});$('diceResults').innerHTML=`<table class="qc-table"><tr><th>Label</th><th>Dice</th><th>IoU</th></tr>${results.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.dice===null?'N/A':r.dice.toFixed(4)}</td><td>${r.iou===null?'N/A':r.iou.toFixed(4)}</td></tr>`).join('')}</table>`;e.target.value=''});bind('setRater',()=>{const reviewer=$('primaryRater').value.trim();C.check(reviewer,'Enter a reviewer ID');if(c.reviewer!==reviewer)c.releaseApproval=null;c.reviewer=reviewer;audit('reviewer-attributed',{caseId:c.id,reviewer});message('Reviewer identity saved.')});bind('approveRelease',()=>{const reviewer=$('releaseRater').value.trim();C.check(c.status==='reviewed'&&!reviewErrors(c).length,'Complete the primary case review first');C.check(reviewer&&c.reviewer&&reviewer!==c.reviewer,'Use a different independent reviewer ID');C.check($('releaseCheck').checked,'Confirm independent review');c.releaseApproval={reviewer,revision:c.annotationRevision||0,at:new Date().toISOString()};audit('independent-review',{caseId:c.id,reviewer,revision:c.annotationRevision||0});message('Independent review recorded for the current annotation revision.');$('dialog').close()})});
bind('releaseSettings',()=>{projectExtensions();const r=project.release,c=current();modal(`<h2>Dataset release records</h2><p>Record the evidence behind permission to train, redistribute and commercially license the dataset. Entries are attestations; this software does not establish ownership, consent or resale rights.</p><div class="control-grid">${[['version','Dataset version'],['steward','Data steward'],['licenseName','License / agreement name'],['sourceReference','Source provenance reference'],['authorizationReference','Authorization / contract reference'],['deidentificationMethod','De-identification method and review']].map(([k,n])=>`<label>${n}<input data-release="${k}" value="${esc(r[k]||'')}"></label>`).join('')}</div>${[['licenseText','Exact license / agreement text'],['intendedUse','Permitted uses and intended training tasks'],['limitations','Known limitations, exclusions and prohibited uses']].map(([k,n])=>`<label>${n}<textarea data-release="${k}" rows="3">${esc(r[k]||'')}</textarea></label>`).join('')}<label class="check"><input id="commercialAuthorized" type="checkbox" ${r.commercialAuthorized?'checked':''}>I have documented authorization for the intended commercial distribution.</label>${c?`<h3>Current case: ${esc(c.id)}</h3>${[['training','Training use permitted'],['redistribution','Redistribution permitted'],['commercial','Commercial use permitted'],['deidentified','De-identification and burned-in image review completed']].map(([k,n])=>`<label class="check"><input data-right="${k}" type="checkbox" ${c.rights?.[k]?'checked':''}>${n}</label>`).join('')}<label>Case authorization reference<input id="caseRightsRef" value="${esc(c.rights?.reference||'')}"></label>`:'<p>Open a case to record its individual rights checks.</p>'}<button id="saveReleaseSettings" class="primary wide">Save release records</button>`);bind('saveReleaseSettings',()=>{for(const el of $('dialogBody').querySelectorAll('[data-release]'))project.release[el.dataset.release]=el.value.trim();project.release.commercialAuthorized=$('commercialAuthorized').checked;if(c){c.rights={reference:$('caseRightsRef').value.trim()};$('dialogBody').querySelectorAll('[data-right]').forEach(el=>c.rights[el.dataset.right]=el.checked)}audit('release-records-updated',{caseId:c?.id||null});$('dialog').close();message('Release records saved. They remain subject to your organization’s verification.')})});
function eligibleCases(){return project.cases.filter(c=>c.status==='reviewed'&&!c.synthetic&&!reviewErrors(c).length)}
function exportSubset(){const anatomy=$('exportAnatomy').value,modality=$('exportModality').value;return eligibleCases().filter(c=>(!anatomy||(c.anatomy||'Unspecified')===anatomy)&&(!modality||c.modality===modality))}
function distribution(cases,key){const counts=Object.create(null);for(const c of cases){const v=String(c[key]||'Unspecified');counts[v]=(counts[v]||0)+1}return counts}
function licenseGate(cases){return [...new Set(cases.flatMap(c=>Quality.releaseErrors(project,c)))]}
bind('export',()=>{projectExtensions();const eligible=eligibleCases();modal(`<h2>Build a dataset release</h2><p>${eligible.length} reviewed, non-practice cases are available. Filter to a consistent anatomy and acquisition family before training.</p><div class="control-grid"><label>Release type<select id="exportType"><option value="training">Internal model training</option><option value="commercial">Commercial release candidate</option></select></label><label>Dataset name<input id="exportName" value="${esc(project.name)}"></label><label>Anatomy<select id="exportAnatomy"><option value="">All anatomies</option>${Object.keys(distribution(eligible,'anatomy')).map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Modality<select id="exportModality"><option value="">All modalities</option>${Object.keys(distribution(eligible,'modality')).map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Training %<input id="trainPct" type="number" value="70" min="1" max="100"></label><label>Validation %<input id="valPct" type="number" value="15" min="0" max="99"></label></div><label>Split seed<input id="seed" value="2026"></label><div id="releaseReadiness" class="info-box"></div><p class="hint">Commercial candidates require per-case usage rights and independent review, and remap case/subject identifiers. Raw DICOM headers, source filenames, private sorting keys and AI conversations are excluded. Burned-in identifying pixels still require manual verification.</p><label class="check"><input id="idsConfirmed" type="checkbox">I verified subject grouping, de-identification, rights and the intended use of this export.</label><button id="buildDataset" class="primary wide">Build dataset ZIP</button>`);function readiness(){const cases=exportSubset(),errors=$('exportType').value==='commercial'?licenseGate(cases):[];$('releaseReadiness').textContent=`${cases.length} cases / ${new Set(cases.map(c=>c.group)).size} subject groups selected.`+(errors.length?'\nRelease requirements:\n'+errors.slice(0,20).join('\n'):'\nReview export metadata and proceed when ready.')}for(const id of ['exportType','exportAnatomy','exportModality'])$(id).onchange=readiness;readiness();bind('buildDataset',async()=>{const cases=exportSubset(),commercial=$('exportType').value==='commercial',name=$('exportName').value.trim(),seed=$('seed').value,train=+$('trainPct').value/100,val=+$('valPct').value/100;C.check(name,'Enter a dataset name');C.check(cases.length,'No eligible cases match this selection');C.check($('idsConfirmed').checked,'Confirm the export checks');C.check(Number.isFinite(train)&&train>0&&Number.isFinite(val),'Enter valid split percentages');const names=project.labels.map(l=>l.name);C.check(new Set(names).size===names.length&&!names.includes('background')&&project.labels.every((l,i)=>l.value===i+1),'nnU-Net requires unique names and consecutive labels 1,2,3…');if(commercial)C.check(!licenseGate(cases).length,licenseGate(cases).join('\n'));const split=C.splitGroups(cases,seed,train,val);$('buildDataset').disabled=true;try{message('Building dataset and SHA-256 manifest locally…');const files={},publicIds={},publicGroups={},training=[],validation=[],test=[],classes=[['case_id','subject_group','split','anatomy','modality',...project.classFields.map(f=>f.name)]],boxes={},qc={},provenance={},members=[],imageFingerprints=new Map();for(let i=0;i<cases.length;i++){const c=cases[i];publicIds[c.id]=commercial?'ECAR_'+String(i+1).padStart(6,'0'):c.id;publicGroups[c.group]=commercial?'SUBJ_'+await sortToken('release:'+project.release.version+':'+c.group):c.group}for(const c of cases){const id=publicIds[c.id],group=publicGroups[c.group],part=split[c.id],suffix=part==='test'?'Ts':'Tr';const imageNifti=C.writeNifti(c),fingerprint=await hashBytes(imageNifti);C.check(!imageFingerprints.has(fingerprint),'Duplicate image volumes detected: '+(imageFingerprints.get(fingerprint)||'')+' and '+c.id+'. Remove the duplicate case before export.');imageFingerprints.set(fingerprint,c.id);files[`segmentation/images${suffix}/${id}_0000.nii.gz`]=await gzip(imageNifti);files[`segmentation/labels${suffix}/${id}.nii.gz`]=await gzip(C.writeNifti(c,c.mask,true));(part==='test'?test:part==='validation'?validation:training).push(id);classes.push([id,group,part,c.anatomy||'Unspecified',c.modality,...project.classFields.map(f=>c.classification[f.name])]);boxes[id]=Object.fromEntries(project.labels.map(l=>[l.value,C.bbox(c,l.value)]));qc[id]={statistics:Quality.statistics(c,project.labels),agreement:c.agreement?.revision===(c.annotationRevision||0)?c.agreement:null};provenance[id]={annotationRevision:c.annotationRevision||0,reviewedAt:c.reviewedAt,primaryReviewer:c.reviewer||'unattributed',independentReview:c.releaseApproval||null,checklist:c.checklist,negative:c.negative,geometry:c.geometry,privacy:c.privacy||null,assistance:c.history.map(h=>({at:h.at,method:String(h.source||'').slice(0,150),voxels:h.voxels})),rights:commercial?c.rights:undefined};members.push({case_id:id,subject_group:group,split:part,anatomy:c.anatomy||'Unspecified',modality:c.modality});files[`landmarks/${id}.mrk.json`]=JSON.stringify({markups:[{type:'Fiducial',coordinateSystem:'LPS',coordinateUnits:'mm',controlPoints:c.landmarks.map((l,j)=>{const ras=c.affine.slice(0,3).map(row=>row[3]+row.slice(0,3).reduce((s,v,q)=>s+v*l.ijk[q],0));return {id:String(j+1),label:l.name,position:[-ras[0],-ras[1],ras[2]],orientation:[1,0,0,0,1,0,0,0,1],selected:true,locked:false,visibility:true,positionStatus:'defined'}})}]},null,2)}
files['segmentation/dataset.json']=JSON.stringify({name,channel_names:{0:cases.every(c=>c.modality==='MR')?'MRI':'image'},labels:{background:0,...Object.fromEntries(project.labels.map(l=>[l.name,l.value]))},numTraining:training.length+validation.length,file_ending:'.nii.gz'},null,2);files['segmentation/splits_final.json']=JSON.stringify([{train:training,val:validation}],null,2);files['splits.json']=JSON.stringify({seed,grouped_by:'subject_group',train:training,validation,test},null,2);files['classification.csv']=csv(classes);files['bounding_boxes.json']=JSON.stringify(boxes,null,2);files['quality_control.json']=JSON.stringify(qc,null,2);files['provenance.json']=JSON.stringify(provenance,null,2);files['case_manifest.json']=JSON.stringify(members,null,2);files['label_definitions.json']=JSON.stringify({labels:project.labels,classFields:project.classFields,landmarkDefinitions:project.landmarkDefinitions,protocol:project.protocol},null,2);files['release_metadata.json']=JSON.stringify({product:project.brand,dataset:name,version:project.release.version||'unversioned',type:commercial?'commercial-release-candidate':'internal-training',created:new Date().toISOString(),scope:'Research dataset; clinical and legal validation not provided by this software',recordedRights:commercial?project.release:null,counts:{cases:cases.length,subjects:new Set(cases.map(c=>c.group)).size,train:training.length,validation:validation.length,test:test.length},anatomy:distribution(cases,'anatomy'),modality:distribution(cases,'modality')},null,2);files['LICENSE.txt']=commercial?project.release.licenseText:'INTERNAL TRAINING EXPORT\nNo redistribution or commercial license is granted by this software. Consult the source data agreements.\n';files['DATASET_CARD.md']=`# ${name}\n\nPrepared with MedAnnotate, a product of Eye Candy Studio for Atom Research.\n\nRelease: ${project.release.version||'Unversioned'}\nType: ${commercial?'Commercial release candidate — rights attestations require organizational verification':'Internal training'}\n\n## Intended use\n${project.release.intendedUse||'Not documented. Define the intended task before training.'}\n\n## Composition\n${cases.length} cases, ${new Set(cases.map(c=>c.group)).size} subject groups. Training ${training.length}, validation ${validation.length}, held-out test ${test.length}.\nAnatomy: ${JSON.stringify(distribution(cases,'anatomy'))}\nModality: ${JSON.stringify(distribution(cases,'modality'))}\nDemographics and sampling representativeness: not captured or inferred by the application.\n\n## Acquisition and annotation\nSee label_definitions.json, case_manifest.json and provenance.json. Annotation is human-reviewed; connected AI advice is unverified. Reviewer identities are self-reported, not authenticated signatures.\n\n## Agreement and quality\nSee quality_control.json. Dice/IoU are included only where a current reference-mask comparison was performed. Missing comparisons are not evidence of agreement.\n\n## Provenance and rights\n${commercial?'Source reference: '+project.release.sourceReference+'\nAuthorization reference: '+project.release.authorizationReference:'Source rights must be checked separately.'}\n\n## De-identification\n${project.release.deidentificationMethod||'Not documented.'}\nOriginal DICOM headers and source paths are not included. Burned-in pixel information and reconstructable facial anatomy may remain; no certified anonymization is asserted.\n\n## Limitations\n${project.release.limitations||'Not documented.'}\nSeparate series remain single-channel cases. No cross-sequence registration, diagnostic validation, fairness evaluation or commercial rights determination is performed by the application.\n\n## Integrity\nSHA256SUMS covers all other files in this release. A checksum verifies bytes, not authenticity or label correctness.\n`;files['README.md']=`# Using this dataset\n\nCopy segmentation into nnUNet_raw/DatasetXXX_Name using an unused dataset ID. After preprocessing, place splits_final.json in the corresponding preprocessed dataset folder and train fold 0. Test images and labels are held out. Check that training/validation subsets are nonempty and that selected series have consistent anatomy, sequences and labels.\n\nFor custom training, classification.csv and case_manifest.json link masks, images, landmarks and subject groups. All image/mask pairs share NIfTI geometry. Bounding box upper bounds are inclusive IJK coordinates; landmarks use LPS millimetres.\n\nSee DATASET_CARD.md, LICENSE.txt and release_metadata.json before use or redistribution. No rights are granted beyond the recorded data license.\n`;
const checksum=[];for(const [path,value] of Object.entries(files)){const bytes=typeof value==='string'?new TextEncoder().encode(value):value;checksum.push(await hashBytes(bytes)+'  '+path)}files['SHA256SUMS']=checksum.join('\n')+'\n';download(C.zip(files),commercial?'MedAnnotate-commercial-candidate.zip':'MedAnnotate-training-dataset.zip');audit('dataset-export',{kind:commercial?'commercial-candidate':'training',cases:cases.length,seed});$('dialog').close();message(`Exported ${cases.length} cases with dataset card, quality report, rights records and file checksums.`)}finally{if($('buildDataset'))$('buildDataset').disabled=false}})});

async function flushSortReceipt(root,manifest){const h=await root.getFileHandle('MedAnnotate-sort-'+sortPlan.id+'.json',{create:true}),stream=await h.createWritable();await stream.write(JSON.stringify(manifest,null,2));await stream.close()}
